use std::env;
use std::fs;
use std::path::PathBuf;

fn main() {
    let manifest_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());
    let cpp_source_dir = manifest_dir.join("shadertool-cpp");

    // 1. Configure CMake build with PIC enabled for proc-macro loading
    let mut config = cmake::Config::new(&cpp_source_dir);
    config
        .define("BUILD_SHARED_LIBS", "OFF")
        .define("CMAKE_POSITION_INDEPENDENT_CODE", "ON");

    let dst = config.build();
    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap());

    // 2. Link C++ static library generated by CMake
    println!("cargo:rustc-link-search=native={}/lib", dst.display());
    println!("cargo:rustc-link-search=native={}/lib64", dst.display());
    println!("cargo:rustc-link-lib=static=shadertool");

    // 3. Platform-specific C++ standard library and system dependencies
    let target = env::var("TARGET").unwrap();
    if target.contains("apple") {
        println!("cargo:rustc-link-lib=dylib=c++");
        println!("cargo:rustc-link-lib=framework=CoreFoundation");
    } else if target.contains("linux") {
        println!("cargo:rustc-link-lib=dylib=stdc++");
        println!("cargo:rustc-link-lib=dylib=pthread");
        println!("cargo:rustc-link-lib=dylib=dl");
        println!("cargo:rustc-link-lib=dylib=m");
    } else if target.contains("windows") {
        println!("cargo:rustc-link-lib=dylib=user32");
        println!("cargo:rustc-link-lib=dylib=shell32");
        println!("cargo:rustc-link-lib=dylib=advapi32");
        println!("cargo:rustc-link-lib=dylib=ole32");
    }

    // 4. Resolve Slang library directory (Custom SLANG_DIR or CMake FetchContent)
    let slang_lib_dir = if let Ok(slang_path) = env::var("SLANG_DIR") {
        PathBuf::from(slang_path).join("lib")
    } else {
        out_dir.join("build/_deps/slang_release-src/lib")
    };

    if slang_lib_dir.exists() {
        println!("cargo:rustc-link-search=native={}", slang_lib_dir.display());
        println!("cargo:rustc-link-lib=dylib=slang");

        // RPATH setup for Unix platforms (Linux / macOS)
        if target.contains("linux") || target.contains("apple") {
            println!(
                "cargo:rustc-link-arg=-Wl,-rpath,{}",
                slang_lib_dir.display()
            );
        }

        // Windows DLL deployment for proc-macro and test execution
        if target.contains("windows") {
            let slang_bin_dir = slang_lib_dir.parent().unwrap().join("bin");
            let slang_dll = if slang_lib_dir.join("slang.dll").exists() {
                slang_lib_dir.join("slang.dll")
            } else {
                slang_bin_dir.join("slang.dll")
            };

            if slang_dll.exists() {
                // Copy slang.dll to target build directories (target/debug and target/debug/deps)
                if let Some(target_dir) = out_dir.ancestors().nth(3) {
                    let _ = fs::copy(&slang_dll, target_dir.join("slang.dll"));
                    let _ = fs::copy(&slang_dll, target_dir.join("deps").join("slang.dll"));
                }
            }
        }
    }

    // 5. Trigger rebuild on C++ source changes
    println!("cargo:rerun-if-changed={}", cpp_source_dir.display());
}
